def variationValues (μ : BoundedScalarCharge 𝕜 Γ) (A : Set Γ) : Set ℝ :=
  {r | ∃ (n : ℕ) (B : Fin n → Set Γ),
    Pairwise (fun i j => Disjoint (B i) (B j)) ∧
    (∀ i, B i ⊆ A) ∧ r = ∑ i, ‖μ (B i)‖}

